Index: app/build.gradle
===================================================================
--- app/build.gradle	
+++ app/build.gradle	
@@ -1,52 +1,56 @@
 plugins {
     id 'com.android.application'
     id 'org.jetbrains.kotlin.android'
 }

 android {
     namespace 'app.yomikaioverlay'
     compileSdk 34

     defaultConfig {
         applicationId 'app.yomikaioverlay'
         minSdk 26
         targetSdk 34
         versionCode 5
         versionName '1.4'
     }

     signingConfigs {
         release {
             storeFile file('../keystore/yomikai-overlay.jks')
             storePassword 'yomikai'
             keyAlias 'overlay'
             keyPassword 'yomikai'
         }
     }

     buildTypes {
         release {
             signingConfig signingConfigs.release
             minifyEnabled false
         }
         debug {
         }
     }

     compileOptions {
         sourceCompatibility JavaVersion.VERSION_17
         targetCompatibility JavaVersion.VERSION_17
     }
     kotlinOptions {
         jvmTarget = '17'
         // LiteRT 2.1.6 собран на более новом Kotlin: метаданные читаем так.
         freeCompilerArgs += ['-Xskip-metadata-version-check', '-Xwhen-guards']
     }
+    testOptions {
+        unitTests.returnDefaultValues = true
+    }
 }

 dependencies {
     // ТОЛЬКО онлайн: LiteRT/TFLite и Tesseract удалены — APK лёгкий.
     implementation 'org.jetbrains.kotlinx:kotlinx-coroutines-android:1.8.1'
     // Edge TTS (WebSocket синтез голосов Microsoft Edge) — как в overlay-translator
     implementation 'com.squareup.okhttp3:okhttp:4.12.0'
+    testImplementation 'junit:junit:4.13.2'
 }

