    }

    private fun dp(v: Int) = TypedValue.applyDimension(
        TypedValue.COMPLEX_UNIT_DIP, v.toFloat(), resources.displayMetrics
    ).toInt()

    private fun rounded(color: Int, rdp: Int) = GradientDrawable().apply {
        setColor(color)
        cornerRadius = dp(rdp).toFloat()
    }

    private fun askNotifPermission() {
        if (android.os.Build.VERSION.SDK_INT >= 33) {
            try {
                if (checkSelfPermission("android.permission.POST_NOTIFICATIONS") != android.content.pm.PackageManager.PERMISSION_GRANTED) {
                    requestPermissions(arrayOf("android.permission.POST_NOTIFICATIONS"), 7)
                }
            } catch (e: Exception) { }
        }
    }

    private fun buildUi() {
        askNotifPermission()
        val root = ScrollView(this)
        val col = LinearLayout(this).apply {
            orientation = LinearLayout.VERTICAL
            setPadding(dp(20), dp(24), dp(20), dp(24))
        }
        root.setBackgroundColor(Color.parseColor("#14161B"))

        val title = TextView(this).apply {
            text = getString(R.string.app_name)
            textSize = 22f
            setTextColor(Color.parseColor("#EEEFF3"))
            gravity = Gravity.CENTER
            setPadding(0, 0, 0, dp(16))
        }
        col.addView(title)

        status = TextView(this).apply {
            textSize = 14f
            setTextColor(Color.parseColor("#AFC0D8"))
            setPadding(0, 0, 0, dp(16))
        }
        col.addView(status)

        fun bigBtn(label: String, onClick: () -> Unit): Button {
            val b = Button(this)
