 * закруглённая карточка с круглыми кнопками: OCR скан (разовый),
 * Авточтение, Стоп чтения, Голос (♀/♂/⚙), Скорость (−/+), Движок,
 * Область (пресеты + удержание для настройки рамки), Панель вниз,
 * Скрыть, Закрыть.
 *
 * UI построен на нативных View (не Compose) — класс крашей
 * «ViewTreeLifecycleOwner not found» здесь невозможен в принципе.
 */
class OverlayService : Service() {

    companion object {
        const val ACTION_START = "app.yomikaioverlay.START"
        const val ACTION_SCAN_ONCE = "app.yomikaioverlay.SCAN_ONCE"
        const val ACTION_AUTO_READ = "app.yomikaioverlay.AUTO_READ"
        const val ACTION_PROJECTION = "app.yomikaioverlay.PROJECTION"
        const val ACTION_READ_TOGGLE = "app.yomikaioverlay.READ_TOGGLE"
        private const val NOTIF_ID = 101
        private const val CH_ID = "ocr_overlay"

        @Volatile
        var running = false
            private set

        fun startForegroundService(ctx: Context) {
            val i = Intent(ctx, OverlayService::class.java)
            i.action = ACTION_START
            try {
                if (Build.VERSION.SDK_INT >= 26) ctx.startForegroundService(i) else ctx.startService(i)
            } catch (e: Exception) {
                ctx.startService(i)
            }
        }

        fun scanOnceNow(ctx: Context) {
            val i = Intent(ctx, OverlayService::class.java)
            i.action = ACTION_SCAN_ONCE
            ctx.startService(i)
        }

        fun autoReadNow(ctx: Context) {
            val i = Intent(ctx, OverlayService::class.java)
            i.action = ACTION_AUTO_READ
            ctx.startService(i)
        }
    }

    // --- Цвета как в читалке ---
    private val cardBg = Color.parseColor("#F2262A34")
    private val btnBg = Color.parseColor("#3D404C")
    private val btnBgAccent = Color.parseColor("#FFC24C")
    private val txtTitle = Color.parseColor("#EEEFF3")
    private val txtSub = Color.parseColor("#AFC0D8")
    private val frameRed = Color.parseColor("#D32F2F")
    private val fabRed = Color.parseColor("#F44336")

    private lateinit var wm: WindowManager
    private lateinit var prefs: android.content.SharedPreferences
    private lateinit var ui: Handler

    private var ocrThread: HandlerThread? = null
    private lateinit var ocrHandler: Handler

    // Окна
    private var mainRoot: LinearLayout? = null
    private var mainLp: WindowManager.LayoutParams? = null
    private var bubbleView: View? = null
    private var panelCard: LinearLayout? = null
    private var previewText: TextView? = null
    private var frameView: View? = null
    private var frameLp: WindowManager.LayoutParams? = null
    private var selectRoot: FrameLayout? = null

    // Состояние
    private var expanded = false
    private var hiddenSnooze = false
    @Volatile private var autoReading = false
    @Volatile private var speaking = false
    private var lastText = ""
    private var repeatCount = 0
    private var preview = ""

    // MediaProjection
    private var projection: MediaProjection? = null
    private var projectionGranted = false

    // OCR: ТОЛЬКО онлайн-движки (Google Lens / Zen Free / Gemini / OpenRouter)
    // — как в overlay-translator. Оффлайн-моделей в APK нет, вес минимальный.
    private val glensOcr by lazy { GlensOcrEngine() }
    private val zenOcr by lazy { ZenFreeOcrEngine(this) }
    private val googleOcr by lazy { GoogleAiOcrEngine(this) }
    private val orOcr by lazy { OpenRouterOcrEngine(this) }
    private val translator by lazy { Translator(this) }

    // TTS: по умолчанию сетевые голоса Edge (как у пользователя везде),
    // системный TTS — резерв/фолбэк.
    private var tts: TextToSpeech? = null
    @Volatile private var ttsReady = false
    @Volatile private var mediaPlayer: MediaPlayer? = null

    private var wakeLock: PowerManager.WakeLock? = null

    private fun dp(v: Number) = TypedValue.applyDimension(
        TypedValue.COMPLEX_UNIT_DIP, v.toFloat(), resources.displayMetrics
    ).toInt()

    private fun screenSize(): Point {
        return if (Build.VERSION.SDK_INT >= 30) {
            val b = wm.currentWindowMetrics.bounds
            Point(b.width(), b.height())
        } else {
            val p = Point()
            @Suppress("DEPRECATION")
            wm.defaultDisplay.getRealSize(p)
            p
        }
    }

    // ------------------------------------------------------------------
    // Жизненный цикл
    // ------------------------------------------------------------------

    override fun onCreate() {
        super.onCreate()
        running = true
        wm = getSystemService(Context.WINDOW_SERVICE) as WindowManager
        prefs = getSharedPreferences("ovr", MODE_PRIVATE)
        ui = Handler(mainLooper)
        val th = HandlerThread("overlay-ocr")
        th.start()
        ocrThread = th
        ocrHandler = Handler(th.looper)
        ensureForeground(false)
        buildWindows()
    }

    override fun onBind(intent: Intent?): IBinder? = null

    override fun onDestroy() {
        running = false
        autoReading = false
        try { tts?.stop(); tts?.shutdown() } catch (e: Exception) { }
        tts = null
        ttsReady = false
        try { projection?.stop() } catch (e: Exception) { }
        projection = null
        projectionGranted = false
        removeAllWindows()
        try { ocrThread?.quitSafely() } catch (e: Exception) { }
        try { wakeLock?.let { if (it.isHeld) it.release() } } catch (e: Exception) { }
        super.onDestroy()
    }

    override fun onStartCommand(intent: Intent?, flags: Int, startId: Int): Int {
        when (intent?.action) {
            ACTION_START -> {
                ensureForeground(projectionGranted)
                showMain(true)
            }
            ACTION_SCAN_ONCE -> {
                ensureForeground(projectionGranted)
                if (!projectionGranted) {
                    CaptureConsentActivity.request(this, "scan")
                } else {
                    scanOnce()
                }
            }
            ACTION_AUTO_READ -> {
                ensureForeground(projectionGranted)
                if (!projectionGranted) {
                    CaptureConsentActivity.request(this, "read")
                } else {
                    startAutoRead()
                }
            }
            ACTION_READ_TOGGLE -> {
                if (autoReading) stopAutoRead() else startAutoReadOrAsk()
            }
            ACTION_PROJECTION -> {
                val rc = intent.getIntExtra("resultCode", 0)
                @Suppress("DEPRECATION")
                val data = if (Build.VERSION.SDK_INT >= 33) {
                    intent.getParcelableExtra("data", Intent::class.java)
                } else {
                    intent.getParcelableExtra("data")
                }
                if (rc != 0 && data != null) {
                    grantProjection(rc, data)
                    when (intent.getStringExtra("next")) {
                        "read" -> startAutoRead()
                        else -> scanOnce()
                    }
                }
            }
        }
        return START_STICKY
    }

    // ------------------------------------------------------------------
    // Foreground: двухфазно (mediaPlayback → +mediaProjection после consent),
    // иначе Android 14+ роняет сервис SecurityException'ом («в других местах»).
    // ------------------------------------------------------------------

    /** Обновляет уведомление сервиса: распознанный текст виден прямо в шторке,
     * плюс кнопки-экшены «OCR скан» и «Авточтение/Стоп». */
    private fun notifyStatus(text: String?) {
        try {
            val nm = getSystemService(Context.NOTIFICATION_SERVICE) as NotificationManager
            val content = if (text.isNullOrBlank()) getString(R.string.notif_text) else text
            val scanPi = PendingIntent.getService(
                this, 1,
                Intent(this, OverlayService::class.java).apply { action = ACTION_SCAN_ONCE },
                PendingIntent.FLAG_UPDATE_CURRENT or PendingIntent.FLAG_IMMUTABLE
            )
            val readPi = PendingIntent.getService(
                this, 2,
                Intent(this, OverlayService::class.java).apply { action = ACTION_READ_TOGGLE },
                PendingIntent.FLAG_UPDATE_CURRENT or PendingIntent.FLAG_IMMUTABLE
            )
            val b: Notification.Builder = if (Build.VERSION.SDK_INT >= 26) {
                Notification.Builder(this, CH_ID)
            } else {
                @Suppress("DEPRECATION")
                Notification.Builder(this)
            }
            b.setSmallIcon(R.drawable.ic_scan)
                .setContentTitle(getString(R.string.app_name))
                .setContentText(if (content.length > 160) content.take(160) + "…" else content)
                .setContentIntent(
                    PendingIntent.getActivity(
                        this, 0, Intent(this, MainActivity::class.java),
                        PendingIntent.FLAG_UPDATE_CURRENT or PendingIntent.FLAG_IMMUTABLE
                    )
                )
                .setOngoing(true)
            if (content.isNotBlank() && content != getString(R.string.notif_text)) {
                b.setStyle(Notification.BigTextStyle().bigText(content))
            }
            b.addAction(Notification.Action.Builder(null, "OCR скан", scanPi).build())
            b.addAction(
                Notification.Action.Builder(
                    null, if (autoReading) "Стоп чтения" else "Авточтение", readPi
                ).build()
            )
            nm.notify(NOTIF_ID, b.build())
        } catch (e: Exception) {
            android.util.Log.w("OverlayService", "notifyStatus: ${e.message}")
        }
    }

    private fun ensureForeground(withProjection: Boolean) {
        val nm = getSystemService(Context.NOTIFICATION_SERVICE) as NotificationManager
        if (Build.VERSION.SDK_INT >= 26) {
            if (nm.getNotificationChannel(CH_ID) == null) {
                val ch = NotificationChannel(CH_ID, getString(R.string.notif_channel), NotificationManager.IMPORTANCE_MIN)
                nm.createNotificationChannel(ch)
            }
        }
        val pi = PendingIntent.getActivity(
            this, 0, Intent(this, MainActivity::class.java),
            PendingIntent.FLAG_UPDATE_CURRENT or PendingIntent.FLAG_IMMUTABLE
        )
        val n: Notification = if (Build.VERSION.SDK_INT >= 26) {
            Notification.Builder(this, CH_ID)
                .setSmallIcon(R.drawable.ic_scan)
                .setContentTitle(getString(R.string.app_name))
                .setContentText(getString(R.string.notif_text))
                .setContentIntent(pi)
                .setOngoing(true)
                .build()
        } else {
            @Suppress("DEPRECATION")
            Notification.Builder(this)
                .setSmallIcon(R.drawable.ic_scan)
                .setContentTitle(getString(R.string.app_name))
                .setContentText(getString(R.string.notif_text))
                .setContentIntent(pi)
                .setOngoing(true)
                .build()
        }
        try {
            if (Build.VERSION.SDK_INT >= 29) {
                var type = ServiceInfo.FOREGROUND_SERVICE_TYPE_MEDIA_PLAYBACK
                if (withProjection) {
                    type = type or ServiceInfo.FOREGROUND_SERVICE_TYPE_MEDIA_PROJECTION
                }
                startForeground(NOTIF_ID, n, type)
            } else {
                startForeground(NOTIF_ID, n)
            }
        } catch (se: SecurityException) {
            // Крайняя страховка: подняться без типа, но сервис должен жить.
            runCatching { startForeground(NOTIF_ID, n) }
        }
    }

