    private fun overlayLp(w: Int, h: Int, touchable: Boolean): WindowManager.LayoutParams {
        var flags = WindowManager.LayoutParams.FLAG_NOT_TOUCH_MODAL or
            WindowManager.LayoutParams.FLAG_LAYOUT_IN_SCREEN
        flags = flags or if (touchable) {
            WindowManager.LayoutParams.FLAG_NOT_FOCUSABLE
        } else {
            WindowManager.LayoutParams.FLAG_NOT_FOCUSABLE or WindowManager.LayoutParams.FLAG_NOT_TOUCHABLE
        }
        val lp = WindowManager.LayoutParams(
            w, h,
            if (Build.VERSION.SDK_INT >= 26) WindowManager.LayoutParams.TYPE_APPLICATION_OVERLAY
            else @Suppress("DEPRECATION") WindowManager.LayoutParams.TYPE_PHONE,
            flags,
            PixelFormat.TRANSLUCENT
        )
        lp.gravity = Gravity.TOP or Gravity.START
        return lp
    }

    private fun rounded(color: Int, rdp: Float) = GradientDrawable().apply {
        setColor(color)
        cornerRadius = dp(rdp).toFloat()
    }

    private fun buildWindows() {
        val s = screenSize()

        // Рамка OCR-области (ненажимаемая, прозрачная)
        frameView = RegionFrameView()
        frameLp = overlayLp(WindowManager.LayoutParams.MATCH_PARENT, WindowManager.LayoutParams.MATCH_PARENT, false)
        try { wm.addView(frameView, frameLp) } catch (e: Exception) { }

        // Пузырь + карточка панели в одном окне
        val root = LinearLayout(this).apply { orientation = LinearLayout.VERTICAL }
        mainRoot = root
        mainLp = overlayLp(WindowManager.LayoutParams.WRAP_CONTENT, WindowManager.LayoutParams.WRAP_CONTENT, true).apply {
            x = s.x - dp(76)
            y = (s.y * 0.42f).toInt()
        }

        val bubble = BubbleView()
        bubbleView = bubble
        val bl = LinearLayout.LayoutParams(dp(56), dp(56))
        bubble.layoutParams = bl
        attachBubbleTouch(bubble)
        root.addView(bubble)

        val gap = View(this)
        gap.layoutParams = LinearLayout.LayoutParams(1, dp(10))
        root.addView(gap)

        val card = LinearLayout(this).apply {
            orientation = LinearLayout.VERTICAL
            background = rounded(cardBg, 18f)
            visibility = View.GONE
            val w = minOf(dp(356f), s.x - dp(24))
            layoutParams = LinearLayout.LayoutParams(w, LinearLayout.LayoutParams.WRAP_CONTENT)
        }
        val pad = dp(8)
        card.setPadding(pad, pad, pad, pad)
        panelCard = card
        root.addView(card)

        try { wm.addView(root, mainLp) } catch (e: Exception) { }
    }

    private fun removeAllWindows() {
        try { selectRoot?.let { wm.removeView(it) } } catch (e: Exception) { }
        selectRoot = null
        try { mainRoot?.let { wm.removeView(it) } } catch (e: Exception) { }
        try { frameView?.let { wm.removeView(it) } } catch (e: Exception) { }
        mainRoot = null
        frameView = null
    }

    private fun showMain(visible: Boolean) {
        hiddenSnooze = !visible
        mainRoot?.visibility = if (visible) View.VISIBLE else View.GONE
        refreshFrame()
    }

    // --- Пузырь: тап = меню; тянуть = переместить ---
    private fun attachBubbleTouch(b: View) {
        val slop = ViewConfiguration.get(this).scaledTouchSlop
        var downX = 0f
        var downY = 0f
        var startX = 0
        var startY = 0
        var moved = false
        b.setOnTouchListener { v, ev ->
            val lp = mainLp ?: return@setOnTouchListener false
            when (ev.actionMasked) {
                MotionEvent.ACTION_DOWN -> {
                    downX = ev.rawX
                    downY = ev.rawY
                    startX = lp.x
                    startY = lp.y
                    moved = false
                    true
                }
                MotionEvent.ACTION_MOVE -> {
                    val dx = ev.rawX - downX
                    val dy = ev.rawY - downY
                    if (!moved && (Math.abs(dx) > slop || Math.abs(dy) > slop)) moved = true
                    if (moved) {
                        val s = screenSize()
                        lp.x = clamp(startX + dx.toInt(), 0, s.x - v.width)
                        lp.y = clamp(startY + dy.toInt(), 0, s.y - v.height)
                        try { wm.updateViewLayout(mainRoot, lp) } catch (e: Exception) { }
                    }
                    true
                }
                MotionEvent.ACTION_UP -> {
                    if (!moved) toggleExpanded()
                    moved = false
                    v.performClick()
                    true
                }
                else -> false
            }
        }
    }

    private fun clamp(v: Int, lo: Int, hi: Int) = if (v < lo) lo else if (v > hi) hi else v

