    private fun regionRatio(): Rect {
        val l = prefs.getFloat("reg_l", 0.025f)
        val t = prefs.getFloat("reg_t", 0.55f)
        val r = prefs.getFloat("reg_r", 0.975f)
        val b = prefs.getFloat("reg_b", 0.98f)
        val s = screenSize()
        return Rect(
            (s.x * l).toInt(), (s.y * t).toInt(),
            (s.x * r).toInt(), (s.y * b).toInt()
        )
    }

    private fun saveRegionRatio(rectPx: Rect) {
        val s = screenSize()
        prefs.edit()
            .putFloat("reg_l", rectPx.left.toFloat() / s.x)
            .putFloat("reg_t", rectPx.top.toFloat() / s.y)
            .putFloat("reg_r", rectPx.right.toFloat() / s.x)
            .putFloat("reg_b", rectPx.bottom.toFloat() / s.y)
            .putString("reg_preset", "custom")
            .apply()
        refreshFrame()
        rebuildPanel()
    }

    private fun regionLabel(): String = when (prefs.getString("reg_preset", "bottom")) {
        "full" -> "Весь экран"
        "top" -> "Верхняя половина"
        "center" -> "Центральная половина"
        "bottom" -> "Нижняя половина"
        else -> "Своя рамка"
    }

    private fun cycleRegionPreset() {
        val s = screenSize()
        when (prefs.getString("reg_preset", "bottom")) {
            "bottom" -> setPreset("full", Rect(0, 0, s.x, s.y))
            "full" -> setPreset("top", Rect(0, 0, s.x, s.y / 2))
            "top" -> setPreset("center", Rect(0, s.y / 4, s.x, (s.y * 0.75f).toInt()))
            else -> setPreset(
                "bottom",
                Rect((s.x * 0.025f).toInt(), (s.y * 0.55f).toInt(), (s.x * 0.975f).toInt(), (s.y * 0.98f).toInt())
            )
        }
    }

    private fun setPreset(name: String, rectPx: Rect) {
        prefs.edit().putString("reg_preset", name).apply()
        saveRegionRatio(rectPx)
        prefs.edit().putString("reg_preset", name).apply()
        frameView?.invalidate()
    }

    private fun refreshFrame() {
        frameView?.visibility =
            if (!hiddenSnooze && (expanded || autoReading)) View.VISIBLE else View.GONE
        frameView?.invalidate()
    }

    private inner class RegionFrameView : View(this@OverlayService) {
        private val p = Paint(Paint.ANTI_ALIAS_FLAG).apply {
            style = Paint.Style.STROKE
            strokeWidth = dp(2.5f).toFloat()
            color = frameRed
            pathEffect = DashPathEffect(floatArrayOf(20f, 12f), 0f)
        }
        override fun onDraw(c: Canvas) {
            val r = regionRatio()
            c.drawRect(
                r.left + 2f, r.top + 2f, r.right - 2f, r.bottom - 2f, p
            )
        }
    }

