    private fun switchEngine(id: String) {
        prefs.edit().putString("ocr_engine", id).apply()
        android.util.Log.i("OverlayOcr", "engine -> $id")
        rebuildPanel()
        val label = engineTitle()
        Toast.makeText(this, "Движок: $label", Toast.LENGTH_SHORT).show()
    }

    private fun setGender(g: String) {
        prefs.edit().putString("gender", g).apply()
        rebuildPanel()
    }

    private fun changeRate(delta: Float) {
        var r = prefs.getFloat("rate", 1.0f) + delta
        if (Math.abs(r - 1.0f) < 0.01f) r = 1.0f
        r = Math.max(0.5f, Math.min(2.0f, (Math.round(r * 100) / 100f)))
        prefs.edit().putFloat("rate", r).apply()
        try { tts?.setSpeechRate(r) } catch (e: Exception) { }
        rebuildPanel()
    }

