    /** Окно выбора голоса: список установленных TTS-голосов, тап = выбрать и прослушать. */
    private var voiceWin: FrameLayout? = null

    private fun openVoicePicker() {
        if (voiceWin != null) return
        ensureTts()
        val container = FrameLayout(this)
        container.setBackgroundColor(Color.parseColor("#CC000000"))
        val card = LinearLayout(this).apply {
            orientation = LinearLayout.VERTICAL
            background = rounded(cardBg, 18f)
        }
        val sp = screenSize()
        val cw = minOf(dp(360), sp.x - dp(24))
        val ch = minOf(dp(460), sp.y - dp(60))
        val scroll = android.widget.ScrollView(this)
        val list = LinearLayout(this).apply { orientation = LinearLayout.VERTICAL }
        val pad = dp(12)
        list.setPadding(pad, pad, pad, pad)
        scroll.addView(list)
        card.addView(scroll, LinearLayout.LayoutParams(cw, ch))

        fun fill() {
            list.removeAllViews()
            val t = tts
            val voices = try { t?.voices?.sortedBy { it.name } } catch (e: Exception) { null }
            val head = TextView(this).apply {
                text = "Выбор голоса (тап = выбрать и прослушать)"
                textSize = 15f
                setTextColor(txtTitle)
                setPadding(dp(4), dp(4), dp(4), dp(10))
            }
            list.addView(head)
            run {
                val hdr = TextView(this).apply {
                    text = "Голоса Edge (онлайн, как в браузере):"
                    textSize = 13f
                    setTextColor(txtSub)
                    setPadding(dp(4), dp(4), dp(4), dp(6))
                }
                list.addView(hdr)
            }
            run {
                var edge = EdgeTts.cachedVoices(this@OverlayService)
                if (edge.isEmpty()) {
                    edge = listOf(
                        EdgeTts.EdgeVoice("ru-RU-SvetlanaNeural", "Female", "ru-RU", "Светлана"),
                        EdgeTts.EdgeVoice("ru-RU-DmitryNeural", "Male", "ru-RU", "Дмитрий"),
                        EdgeTts.EdgeVoice("ru-RU-DariyaNeural", "Female", "ru-RU", "Дарья"),
                    )
                }
                val cur = prefs.getString("voice_name", "")
                for (v in edge.filter { it.locale.startsWith("ru-", true) || it.multilingual }.take(24)) {
                    val key = "edge:" + v.shortName
                    val row = TextView(this).apply {
                        text = (if (cur == key) "✅ " else "") + v.label
                        textSize = 13f
                        setTextColor(if (cur == key) btnBgAccent else txtTitle)
                        setPadding(dp(8), dp(10), dp(8), dp(10))
                        background = rounded(Color.parseColor("#2E323E"), 10f)
                    }
                    val lp = LinearLayout.LayoutParams(LinearLayout.LayoutParams.MATCH_PARENT, LinearLayout.LayoutParams.WRAP_CONTENT)
                    lp.setMargins(0, 0, 0, dp(6))
                    row.layoutParams = lp
                    row.setOnClickListener {
                        prefs.edit()
                            .putString("voice_name", key)
                            .putString("edge_voice", v.shortName)
                            .putString("tts_backend", "edge")
                            .apply()
                        closeVoicePicker()
                        speakNowSilentPreview("Привет! Это мой голос. Желаю приятного чтения.")
                    }
                    list.addView(row)
                }
            }
            run {
                val hdr2 = TextView(this).apply {
                    text = "Системные голоса телефона:"
                    textSize = 13f
                    setTextColor(txtSub)
                    setPadding(dp(4), dp(10), dp(4), dp(6))
                }
                list.addView(hdr2)
            }
            if (voices.isNullOrEmpty()) {
                val m = TextView(this).apply {
                    text = "TTS ещё не готов или голосов нет. Откройте системные настройки TTS (⚙) и загрузите русские голоса."
                    textSize = 13f
                    setTextColor(txtSub)
                    setPadding(dp(4), dp(6), dp(4), dp(6))
                }
                list.addView(m)
            } else {
                val cur = prefs.getString("voice_name", "")
                for (v in voices) {
                    val net = try { v.isNetworkConnectionRequired } catch (e: Exception) { false }
                    val row = TextView(this).apply {
                        text = (if (v.name == cur) "✅ " else "") + v.name + "\n" +
                            v.locale.displayName + (if (net) " · сетевой" else " · локальный")
                        textSize = 13f
                        setTextColor(if (v.name == cur) btnBgAccent else txtTitle)
                        setPadding(dp(8), dp(10), dp(8), dp(10))
                        background = rounded(Color.parseColor("#2E323E"), 10f)
                    }
                    val lp = LinearLayout.LayoutParams(LinearLayout.LayoutParams.MATCH_PARENT, LinearLayout.LayoutParams.WRAP_CONTENT)
                    lp.setMargins(0, 0, 0, dp(6))
                    row.layoutParams = lp
                    row.setOnClickListener {
                        prefs.edit()
                            .putString("voice_name", v.name)
                            .putString("tts_backend", "system")
                            .apply()
                        try { t?.voice = v } catch (e: Exception) { }
                        closeVoicePicker()
                        // проба: сразу озвучиваем короткую фразу выбранным голосом
                        speakNowSilentPreview("Привет! Это мой голос. Желаю приятного чтения.")
                    }
                    list.addView(row)
                }
            }
        }
        fill()
        Thread {
            try {
                val fresh = runBlocking { EdgeTts.fetchVoices() }
                if (fresh.isNotEmpty()) {
                    EdgeTts.cacheVoices(this@OverlayService, fresh)
                    ui.post { if (voiceWin != null) fill() }
                }
            } catch (e: Exception) {
                android.util.Log.d("Edge", "fetchVoices: ${e.message}")
            }
        }.start()
        if (voicesNoneYet(list)) {
            // TTS асинхронный: перечитать список через секунду
            ui.postDelayed({ if (voiceWin != null) fill() }, 900)
        }

        container.addView(card)
        val clp = FrameLayout.LayoutParams(FrameLayout.LayoutParams.WRAP_CONTENT, FrameLayout.LayoutParams.WRAP_CONTENT)
        clp.gravity = Gravity.CENTER
        card.layoutParams = clp
        container.setOnClickListener { closeVoicePicker() }
        card.setOnClickListener { } // гасим клики по карточке
        val lp = overlayLp(WindowManager.LayoutParams.MATCH_PARENT, WindowManager.LayoutParams.MATCH_PARENT, true)
        try { wm.addView(container, lp) } catch (e: Exception) { }
        voiceWin = container
        rebuildPanel()
    }

    private fun voicesNoneYet(list: LinearLayout): Boolean {
        val t = tts ?: return true
        return try { !ttsReady || t.voices.isNullOrEmpty() } catch (e: Exception) { true }
    }

    private fun closeVoicePicker() {
        try { voiceWin?.let { wm.removeView(it) } } catch (e: Exception) { }
        voiceWin = null
        rebuildPanel()
    }

    /** Пробная фраза: без пометки «идёт чтение» — просто прослушать голос. */
    private fun speakNowSilentPreview(phrase: String) {
        if (ttsBackend() == "edge") {
            speakEdge(phrase)
            return
        }
        val t = tts ?: run { ui.postDelayed({ speakNowSilentPreview(phrase) }, 600); return }
        if (!ttsReady) { ui.postDelayed({ speakNowSilentPreview(phrase) }, 600); return }
        try {
            t.language = pickLocale(phrase)
            applyVoicePref(t)
            t.setSpeechRate(prefs.getFloat("rate", 1.0f))
            t.setPitch(if (prefs.getString("gender", "female") == "male") 0.82f else 1.15f)
            t.speak(phrase, TextToSpeech.QUEUE_FLUSH, android.os.Bundle(), "ovr-preview")
        } catch (e: Exception) { }
    }

    private fun ttsBackend(): String = prefs.getString("tts_backend", "edge") ?: "edge"

    /** Edge-голос: явный выбор из списка, иначе по тембру ♀/♂. */
    private fun edgeVoiceName(): String {
        val custom = prefs.getString("edge_voice", "") ?: ""
        if (custom.isNotBlank()) return custom
        return if (prefs.getString("gender", "female") == "male") "ru-RU-DmitryNeural" else "ru-RU-SvetlanaNeural"
    }

    private fun pickLocale(text: String): Locale {
        var cyr = 0
        var lat = 0
        for (ch in text) {
            if (ch in 'А'..'я' || ch == 'Ё' || ch == 'ё') cyr++
            else if (ch in 'A'..'Z' || ch in 'a'..'z') lat++
        }
        return if (cyr >= lat) Locale("ru", "RU") else Locale.ENGLISH
    }

    private fun speak(text: String) {
        if (text.isBlank()) return
        ensureTts()
        val t = tts
        if (t == null || !ttsReady) {
            if (tts == null) ensureTts()
            // повторим через мгновение
            ui.postDelayed({ speakNow(text) }, 650)
            return
        }
        speakNow(text)
    }

    private fun speakNow(text: String) {
        if (ttsBackend() == "edge") {
            speakEdge(text)
            return
        }
        speakNowSystem(text)
    }

    private fun speakNowSystem(text: String) {
        val t = tts ?: return
        try {
            t.language = pickLocale(text)
            applyVoicePref(t)
            t.setSpeechRate(prefs.getFloat("rate", 1.0f))
            t.setPitch(if (prefs.getString("gender", "female") == "male") 0.82f else 1.15f)
            speaking = true
            val params = android.os.Bundle()
            t.speak(text, TextToSpeech.QUEUE_FLUSH, params, "ovr-utterance")
        } catch (e: Exception) {
            speaking = false
        }
    }

    /** Синтез сетевым голосом Edge: тексты уходят в Microsoft, кадры — никогда. */
    private fun speakEdge(text: String) {
        speaking = true
        val voice = edgeVoiceName()
        val rate = prefs.getFloat("rate", 1.0f)
        val pitch = if (prefs.getString("gender", "female") == "male") 0.82f else 1.15f
        Thread {
            var ok = false
            try {
                val ratePercent = ((rate - 1f) * 100f).roundToInt()
                val pitchHz = ((pitch - 1f) * 200f).roundToInt()
                val file = runBlocking {
                    EdgeTts.synthesizeToFile(applicationContext, text, voice, ratePercent, pitchHz)
                }
                if (file != null) {
                    ok = true
                    ui.post { playEdgeAudio(file) }
                }
            } catch (e: Exception) {
                android.util.Log.w("Edge", "speakEdge: ${e.message}")
            }
            if (!ok) {
                // нет сети/сервер недоступен → фолбэк на системный TTS
                ui.post { speakNowSystem(text) }
            }
        }.start()
    }

    private fun playEdgeAudio(file: java.io.File) {
        try {
            runCatching { mediaPlayer?.release() }
            val mp = MediaPlayer()
            mediaPlayer = mp
            mp.setAudioAttributes(
                AudioAttributes.Builder()
                    .setUsage(AudioAttributes.USAGE_MEDIA)
                    .setContentType(AudioAttributes.CONTENT_TYPE_SPEECH)
                    .build(),
            )
            mp.setDataSource(file.absolutePath)
            mp.setOnErrorListener { _, _, _ ->
                runCatching { file.delete() }
                speaking = false
                true
            }
            mp.setOnPreparedListener { media ->
                media.start()
            }
            mp.setOnCompletionListener { done ->
                runCatching { done.release() }
                mediaPlayer = null
                runCatching { file.delete() }
                speaking = false
                if (autoReading) {
                    ui.postDelayed({ if (autoReading) scrollAndContinue() }, 350)
                }
            }
            mp.prepareAsync()
        } catch (e: Exception) {
            android.util.Log.w("Edge", "playback: ${e.message}")
            runCatching { file.delete() }
            speaking = false
        }
    }

    // ------------------------------------------------------------------
    // Сценарии чтения
    // ------------------------------------------------------------------

    private fun scanOnce() {
        preview = "Сканирую…"
        previewText?.text = preview
        notifyStatus("Сканирую рамку…")
        refreshFrame()
        ocrScan { text ->
            if (text.isBlank()) {
                preview = "Текст не найден в рамке"
                previewText?.text = preview
                notifyStatus("Текст не найден в рамке")
                return@ocrScan
            }
            preview = text
            previewText?.text = preview
            setExpanded(true)
            notifyStatus(text) // распознанное текстом видно в шторке
            speak(text)
        }
    }

    private fun startAutoRead() {
        if (autoReading) return
        autoReading = true
        lastText = ""
        repeatCount = 0
        setExpanded(true)
        rebuildPanel()
        refreshFrame()
        try {
            val pm = getSystemService(Context.POWER_SERVICE) as PowerManager
            @Suppress("DEPRECATION")
            wakeLock = pm.newWakeLock(PowerManager.PARTIAL_WAKE_LOCK, "ovr:read")
            wakeLock?.acquire(30 * 60 * 1000L)
        } catch (e: Exception) { }
        autoStep()
    }

    fun stopAutoRead() {
        autoReading = false
        try { tts?.stop() } catch (e: Exception) { }
        runCatching { mediaPlayer?.let { if (it.isPlaying) it.stop(); it.release() } }
        mediaPlayer = null
        speaking = false
        rebuildPanel()
        refreshFrame()
        notifyStatus(if (preview.isNotBlank()) preview else null)
    }

    private fun autoStep() {
        if (!autoReading) return
        ocrScan { text ->
            if (!autoReading) return@ocrScan
            val norm = norm(text)
            if (norm.isBlank() || norm == lastText) {
                repeatCount++
                scrollAndContinue()
                return@ocrScan
            }
            repeatCount = 0
            lastText = norm
            preview = text
            previewText?.text = preview
            notifyStatus(text)
            speak(text)
            // продолжение — из onDone говорилки
        }
    }

    private fun scrollAndContinue() {
        val r = regionRatio()
        val svc = ScrollAccessibilityService.instance
        if (svc != null) {
            try { svc.swipeForward(r.left, r.top, r.right, r.bottom) } catch (e: Exception) { }
            ui.postDelayed({ if (autoReading) autoStep() }, 1250)
        } else {
            // Автопрокрутка выключена: ждём и читаем то же место снова (так видно,
            // что службу спецвозможностей нужно включить — есть подсказка в меню).
            ui.postDelayed({
                if (!autoReading) return@postDelayed
                preview = "⚠ Автопрокрутка выключена — включите «Yomikai Оверлей — прокрутка» в спец. возможностях"
                previewText?.text = preview
                lastText = "" // пусть перечитает после включения/ручной прокрутки
                ui.postDelayed({ if (autoReading) autoStep() }, 2500)
            }, 600)
        }
    }

    private fun norm(s: String) = s.lowercase().replace("\\s+".toRegex(), " ").trim()

    override fun onConfigurationChanged(newConfig: Configuration) {
        super.onConfigurationChanged(newConfig)
        refreshFrame()
    }
}

package app.yomikaioverlay

import android.content.Context
import android.util.Log
import kotlinx.coroutines.CancellationException
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.suspendCancellableCoroutine
import kotlinx.coroutines.withContext
import okhttp3.OkHttpClient
import okhttp3.Request
import okhttp3.Response
import okhttp3.WebSocket
import okhttp3.WebSocketListener
import okio.ByteString
import java.io.File
import java.net.HttpURLConnection
import java.net.URL
import java.security.MessageDigest
import java.util.GregorianCalendar
import java.util.Locale
import java.util.TimeZone
import java.util.UUID
import java.util.concurrent.TimeUnit
import kotlin.coroutines.resume

/**
 * Клиент бесплатной онлайн-озвучки Microsoft Edge (edge-tts): те же WebSocket-
 * endpoint и голоса, что использует «Читать вслух» в браузере Edge.
 *
 * API-ключ не требуется — только интернет. Голоса отдаются MP3, который
 * приложение проигрывает системным MediaPlayer. Только текст реплики
 * отправляется в Microsoft; изображения/OCR-кадры никогда не отправляются.
 *
 * Протокол (из библиотеки rany2/edge-tts):
 *  - список голосов — GET voices/list;
 *  - синтез — WebSocket wss://speech.platform.bing.com/.../edge/v1;
 *  - Sec-MS-GEC — SHA-256 от (Windows file-time, округлённого до 5 минут)
 *    + trusted-токен; иначе сервер закрывает соединение.
 */
object EdgeTts {
    private const val TAG = "EdgeTts"

    private const val TRUSTED_CLIENT_TOKEN = "6A5AA1D4EAFF4E9FB37E23D68491D6F4"
    /** Разница эпох Unix (1970) и Windows file time (1601), в секундах. */
    private const val WIN_EPOCH = 11_644_473_600L
    private const val CHROMIUM_FULL_VERSION = "143.0.3650.75"
    private const val CHROMIUM_MAJOR = "143"
    private const val SEC_MS_GEC_VERSION = "1-$CHROMIUM_FULL_VERSION"

    private const val BASE_URL =
        "speech.platform.bing.com/consumer/speech/synthesize/readaloud"
    private const val VOICE_LIST_URL =
        "https://$BASE_URL/voices/list?trustedclienttoken=$TRUSTED_CLIENT_TOKEN"
    private const val WSS_URL =
        "wss://$BASE_URL/edge/v1?TrustedClientToken=$TRUSTED_CLIENT_TOKEN"

    /** Голос по умолчанию: русский женский (нейтральный). */
    const val DEFAULT_VOICE = "ru-RU-SvetlanaNeural"

    /** Предел одного SSML-запроса — Microsoft режет длиннее 4096 байт. */
    private const val SSML_BYTE_LIMIT = 4000

    private val client by lazy {
        OkHttpClient.Builder()
            .connectTimeout(15, TimeUnit.SECONDS)
            .readTimeout(90, TimeUnit.SECONDS)
            .pingInterval(10, TimeUnit.SECONDS)
            .build()
    }

    private val userAgent =
        "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 " +
            "(KHTML, like Gecko) Chrome/$CHROMIUM_MAJOR.0.0.0 Safari/537.36 " +
            "Edg/$CHROMIUM_MAJOR.0.0.0"

    /** Один голос Edge TTS из публичного списка. */
    data class EdgeVoice(
        val shortName: String,
        val gender: String,
        val locale: String,
        val friendlyName: String,
    ) {
        /** Мультиязычные голоса понимают текст на любом из больших языков. */
        val multilingual: Boolean get() = shortName.contains("Multilingual", ignoreCase = true)
        val language: String get() = locale.substringBefore('-').lowercase()
        val genderIcon: String get() = when {
            gender.contains("Female", true) -> "♀"
            gender.contains("Male", true) -> "♂"
            else -> "•"
        }
        /** Короткая подпись для списка: название • пол • язык (+ 🌐). */
        val label: String
            get() = buildString {
                append(shortName)
                append(" • ").append(genderIcon)
                append(" ").append(locale)
                if (multilingual) append(" • 🌐 мультиязычный")
            }
    }

    /**
     * Sec-MS-GEC токен: SHA-256 от (Windows-file-time, округлённого до 5 минут)
     * + trusted-токен. Без него сервер отвечает 403/закрывает вебсокет.
     */
    fun secMsGec(nowEpochSeconds: Long = System.currentTimeMillis() / 1000): String {
        var ticks = nowEpochSeconds + WIN_EPOCH
        ticks -= ticks % 300L
        val windowsTicks = ticks * 10_000_000L
        val digest = MessageDigest.getInstance("SHA-256")
            .digest("$windowsTicks$TRUSTED_CLIENT_TOKEN".toByteArray(Charsets.US_ASCII))
        return digest.joinToString("") { "%02X".format(it.toInt() and 0xFF) }
    }

    /** «Javascript-стиль» дата-строка, которую ждёт сервер в X-Timestamp. */
    private fun jsTimestamp(): String {
        val cal = GregorianCalendar(TimeZone.getTimeZone("UTC"))
        val days = arrayOf("Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat")
        val months = arrayOf("Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec")
        return String.format(
            Locale.US,
            "%s %s %02d %04d %02d:%02d:%02d GMT+0000 (Coordinated Universal Time)",
            days[cal.get(GregorianCalendar.DAY_OF_WEEK) - 1],
            months[cal.get(GregorianCalendar.MONTH)],
            cal.get(GregorianCalendar.DAY_OF_MONTH),
            cal.get(GregorianCalendar.YEAR),
            cal.get(GregorianCalendar.HOUR_OF_DAY),
            cal.get(GregorianCalendar.MINUTE),
            cal.get(GregorianCalendar.SECOND),
        )
    }

    private fun uuidHex(): String = UUID.randomUUID().toString().replace("-", "")

    private fun escapeXml(s: String): String = buildString {
        for (c in s) {
            when (c) {
                '&' -> append("&amp;")
                '<' -> append("&lt;")
                '>' -> append("&gt;")
                '"' -> append("&quot;")
                '\'' -> append("&apos;")
                else -> append(c)
            }
        }
    }

    /**
     * Список всех голосов Edge TTS. Пустой список при ошибке сети/403.
     */
    suspend fun fetchVoices(): List<EdgeVoice> = withContext(Dispatchers.IO) {
        runCatching {
            val conn = URL(VOICE_LIST_URL +
                "&Sec-MS-GEC=${secMsGec()}&Sec-MS-GEC-Version=$SEC_MS_GEC_VERSION")
                .openConnection() as HttpURLConnection
            conn.connectTimeout = 15_000
            conn.readTimeout = 30_000
            conn.setRequestProperty("User-Agent", userAgent)
            conn.setRequestProperty("Authority", "speech.platform.bing.com")
            conn.setRequestProperty("Accept", "*/*")
            conn.setRequestProperty("Sec-Fetch-Site", "none")
            conn.setRequestProperty("Sec-Fetch-Mode", "cors")
            conn.setRequestProperty("Sec-Fetch-Dest", "empty")
            conn.setRequestProperty("Sec-CH-UA-Mobile", "?0")
            if (conn.responseCode !in 200..299) {
                Log.w(TAG, "voices HTTP ${conn.responseCode}")
                return@runCatching emptyList<EdgeVoice>()
            }
            val body = conn.inputStream.bufferedReader().readText()
            conn.disconnect()
            val arr = org.json.JSONArray(body)
            buildList {
                for (i in 0 until arr.length()) {
                    val v = arr.optJSONObject(i) ?: continue
                    val short = v.optString("ShortName")
                    if (short.isBlank()) continue
                    val locale = v.optString("Locale").ifBlank { "xx-XX" }
                    add(
                        EdgeVoice(
                            shortName = short,
                            gender = v.optString("Gender"),
                            locale = locale,
                            friendlyName = v.optString("FriendlyName").ifBlank { short },
                        ),
                    )
                }
            }.sortedWith(
                compareBy(
                    { it.friendlyName.contains("Multilingual", true) },
                    { it.locale },
                    { it.shortName },
                ),
            )
        }.getOrElse { error ->
            Log.w(TAG, "voice list fetch failed", error)
            emptyList()
        }
    }

    /**
     * Синтез одного текста в файл MP3. [ratePercent]/[pitchHz] — prosody
     * (0 = обычный голос). Вернёт null при ошибке сети/сервера/пустого результата.
     */
    suspend fun synthesizeToFile(
        context: Context,
        text: String,
        voice: String = DEFAULT_VOICE,
        ratePercent: Int = 0,
        pitchHz: Int = 0,
    ): File? = withContext(Dispatchers.IO) {
        val target = File(context.cacheDir, "tts_edge_${System.nanoTime()}.mp3")
        val out = target.outputStream().buffered()
        var any = false
        try {
            for (chunk in chunkForSsml(text)) {
                val data = speakChunk(chunk, voice, ratePercent, pitchHz, 0)
                if (data.isEmpty()) {
                    Log.w(TAG, "empty chunk for voice $voice")
                    continue
                }
                out.write(data)
                any = true
            }
            if (!any) null else target
        } catch (e: CancellationException) {
            throw e
        } catch (e: Exception) {
            Log.w(TAG, "synthesis failed", e)
            null
        } finally {
            runCatching { out.close() }
            if (!any && target.exists()) target.delete()
        }
    }

    /**
     * Разбивает текст на куски ≤ [SSML_BYTE_LIMIT] байт UTF-8, не режа символы:
     * большой текст уходит несколькими SSML-запросами.
     */
    private fun chunkForSsml(text: String, limit: Int = SSML_BYTE_LIMIT): List<String> {
        if (text.toByteArray(Charsets.UTF_8).size <= limit) return listOf(text)
        val chunks = mutableListOf<String>()
        val rest = StringBuilder(text)
        while (rest.isNotEmpty()) {
            var take = limit
            while (take > 0) {
                val candidate = rest.substring(0, take)
                if (candidate.isWholeUtf8()) break
                take--
            }
            if (take <= 0) take = limit
            var part = rest.substring(0, take)
            val amp = part.lastIndexOf('&')
            if (amp >= 0 && part.indexOf(';', amp) < 0 && part.length > amp + 1) {
                part = part.substring(0, amp)
            }
            chunks += part.trim()
            rest.delete(0, part.length)
        }
        return chunks.filter(String::isNotBlank)
    }

    private fun String.isWholeUtf8(): Boolean = try {
        this.toByteArray(Charsets.UTF_8).toString(Charsets.UTF_8) == this
    } catch (e: Exception) {
        false
    }

    /** Один SSML-запрос на WebSocket, возвращает конкатенированный MP3. */
    private suspend fun speakChunk(
        text: String,
        voice: String,
        ratePercent: Int,
        pitchHz: Int,
        volumePercent: Int,
    ): ByteArray = suspendCancellableCoroutine { cont ->
        val requestId = uuidHex()
        val url = WSS_URL +
            "&Sec-MS-GEC=${secMsGec()}" +
            "&Sec-MS-GEC-Version=$SEC_MS_GEC_VERSION" +
            "&ConnectionId=$requestId"
        val request = Request.Builder()
            .url(url)
            .header("User-Agent", userAgent)
            .header("Pragma", "no-cache")
            .header("Cache-Control", "no-cache")
            .header("Origin", "chrome-extension://jdiccldimpdaibmpdkjnbmckianbfold")
            .header("Sec-WebSocket-Version", "13")
            .header("Cookie", "muid=${uuidHex().uppercase()};")
            .build()
        val ws = client.newWebSocket(request, EdgeSocketListener(
            requestId = requestId,
            voice = voice,
            text = text,
            ratePercent = ratePercent,
            pitchHz = pitchHz,
            volumePercent = volumePercent,
            onResult = { bytes -> if (cont.isActive) cont.resume(bytes) },
            onError = { error ->
                if (cont.isActive) cont.resume(ByteArray(0))
                if (error != null) Log.w(TAG, "websocket error", error)
            },
        ))
        cont.invokeOnCancellation { ws.cancel() }
    }

    /** Собирает MP3 из бинарных аудио-сообщений WebSocket-соединения. */
    private class EdgeSocketListener(
        private val requestId: String,
        private val voice: String,
        private val text: String,
        private val ratePercent: Int,
        private val pitchHz: Int,
        private val volumePercent: Int,
        private val onResult: (ByteArray) -> Unit,
        private val onError: (Throwable?) -> Unit,
    ) : WebSocketListener() {

        private val audio = java.io.ByteArrayOutputStream()
        private var finished = false

        override fun onOpen(webSocket: WebSocket, response: Response) {
            val ts = jsTimestamp()
            webSocket.send(
                "X-Timestamp:$ts\r\n" +
                    "Content-Type:application/json; charset=utf-8\r\n" +
                    "Path:speech.config\r\n\r\n" +
                    "{\"context\":{\"synthesis\":{\"audio\":{\"metadataoptions\":" +
                    "{\"sentenceBoundaryEnabled\":\"false\",\"wordBoundaryEnabled\":\"true\"}," +
                    "\"outputFormat\":\"audio-24khz-48kbitrate-mono-mp3\"}}}}\r\n",
            )
            val s = escapeXml(text)
            val rate = if (ratePercent >= 0) "+$ratePercent%" else "$ratePercent%"
            val pitch = if (pitchHz >= 0) "+${pitchHz}Hz" else "${pitchHz}Hz"
            val vol = if (volumePercent >= 0) "+$volumePercent%" else "$volumePercent%"
            val ssml =
                "<speak version='1.0' xmlns='http://www.w3.org/2001/10/synthesis' " +
                    "xml:lang='en-US'><voice name='$voice'>" +
                    "<prosody pitch='$pitch' rate='$rate' volume='$vol'>$s</prosody>" +
                    "</voice></speak>"
            webSocket.send(
                "X-RequestId:$requestId\r\n" +
                    "Content-Type:application/ssml+xml\r\n" +
                    "X-Timestamp:${ts}Z\r\n" +
                    "Path:ssml\r\n\r\n$ssml",
            )
        }

        override fun onMessage(webSocket: WebSocket, text: String) {
            if (text.contains("turn.end")) finish(webSocket)
        }

        override fun onMessage(webSocket: WebSocket, bytes: ByteString) {
            val n = bytes.size
            if (n < 2) return
            val headerLength = ((bytes[0].toInt() and 0xFF) shl 8) or (bytes[1].toInt() and 0xFF)
            if (2 + headerLength > n) return
            val header = bytes.substring(2, 2 + headerLength).utf8()
            if (header.contains("Path:audio", ignoreCase = true) &&
                header.contains("Content-Type:audio/mpeg", ignoreCase = true)
            ) {
                val data = bytes.substring(2 + headerLength)
                if (data.size > 0) audio.write(data.toByteArray())
            }
        }

        override fun onFailure(webSocket: WebSocket, t: Throwable, response: Response?) {
            if (!finished) {
                finished = true
                onError(t)
            }
        }

        private fun finish(webSocket: WebSocket) {
            if (finished) return
            finished = true
            runCatching { webSocket.close(1000, "ok") }
            onResult(audio.toByteArray())
        }
    }

    /* ─── кэш списка голосов (для оффлайн-показа в диалогах) ─── */

    private fun cacheFile(ctx: Context): File = File(ctx.filesDir, "edge_voices.json")

    fun cacheVoices(ctx: Context, voices: List<EdgeVoice>) {
        runCatching {
            val arr = org.json.JSONArray().apply {
                voices.forEach { v ->
                    put(
                        org.json.JSONObject().apply {
                            put("ShortName", v.shortName)
                            put("Gender", v.gender)
                            put("Locale", v.locale)
                            put("FriendlyName", v.friendlyName)
                        },
                    )
                }
            }
            cacheFile(ctx).writeText(arr.toString())
        }.onFailure { Log.w(TAG, "cache write failed", it) }
    }

    fun cachedVoices(ctx: Context): List<EdgeVoice> = runCatching {
        val f = cacheFile(ctx)
        if (!f.isFile) return@runCatching emptyList<EdgeVoice>()
        val arr = org.json.JSONArray(f.readText())
        buildList {
            for (i in 0 until arr.length()) {
                val v = arr.optJSONObject(i) ?: continue
                val short = v.optString("ShortName")
                if (short.isBlank()) continue
                add(
                    EdgeVoice(
                        shortName = short,
                        gender = v.optString("Gender"),
                        locale = v.optString("Locale").ifBlank { "xx-XX" },
                        friendlyName = v.optString("FriendlyName").ifBlank { short },
                    ),
                )
            }
        }
    }.getOrElse { emptyList() }
}

package app.yomikaioverlay.ot

import android.graphics.Bitmap
import android.util.Log
import java.io.ByteArrayOutputStream
import java.io.IOException
import java.net.HttpURLConnection
import java.net.URL
import kotlin.random.Random

/**
 * Google Lens OCR via protobuf endpoint.
 * Ported from Yomihon's GlensOcrEngine.
 *
 * Falls back gracefully: returns empty string on any error so that
 * [OcrRouter] can try the next engine.
 */
class GlensOcrEngine : OcrEngine {

    override fun recognizeText(image: Bitmap): String {
        require(!image.isRecycled) { "Input bitmap is recycled" }
        val maxDim = maxOf(image.width, image.height)
        val resized = if (maxDim > MAX_IMAGE_DIMENSION) {
            val s = MAX_IMAGE_DIMENSION.toFloat() / maxDim.toFloat()
            Bitmap.createScaledBitmap(image, 
                (image.width * s).toInt().coerceAtLeast(1),
                (image.height * s).toInt().coerceAtLeast(1),
                true,
            )
        } else null
        val working = resized ?: image
        return try {
            val encoded = ByteArrayOutputStream()
            if (!working.compress(Bitmap.CompressFormat.PNG, 100, encoded))
                throw IOException("PNG encode failed")
            val payload = buildRequestPayload(encoded.toByteArray(), working.width, working.height)
            val resp = executeRequest(payload)
            extractText(resp)
        } catch (e: Exception) {
            Log.w(TAG, "Glens failed, returning empty", e)
            ""
        } finally {
            resized?.recycle()
        }
    }

    /* ─────────── Request ─────────── */

    private fun buildRequestPayload(pngBytes: ByteArray, w: Int, h: Int): ByteArray {
        // Must be non-negative for uint64 varint encoding
        val requestId = Random.nextLong().toLong() and Long.MAX_VALUE
        return ProtoWriter().apply {
            writeMessage(1) { objReq ->
                // objects_request_context
                objReq.writeMessage(1) { ctx ->
                    // request_id
                    ctx.writeMessage(3) { rid ->
                        rid.writeUInt64(1, requestId)
                        rid.writeInt32(2, 0)
                        rid.writeInt32(3, 0)
                        rid.writeBytes(4, Random.nextBytes(16))
                    }
                    // client_context
                    ctx.writeMessage(4) { cc ->
                        cc.writeInt32(1, PLATFORM_WEB)
                        cc.writeInt32(2, SURFACE_CHROMIUM)
                        cc.writeMessage(4) { lc ->
                            lc.writeString(1, DEFAULT_CLIENT_LANGUAGE)
                            lc.writeString(2, DEFAULT_CLIENT_REGION)
                        }
                        cc.writeMessage(7) { filters ->
                            filters.writeMessage(1) { fl ->
                                fl.writeInt32(1, AUTO_FILTER)
                            }
                        }
                    }
                }
                // image_data
                objReq.writeMessage(3) { img ->
                    img.writeMessage(1) { p ->
                        p.writeBytes(1, pngBytes)
                    }
                    img.writeMessage(3) { m ->
                        m.writeInt32(1, w)
                        m.writeInt32(2, h)
                    }
                }
            }
        }.toByteArray()
    }

    /* ─────────── HTTP ─────────── */

    private fun executeRequest(payload: ByteArray): ByteArray {
        val conn = (URL(LENS_ENDPOINT).openConnection() as HttpURLConnection).apply {
            requestMethod = "POST"
            doOutput = true
            connectTimeout = 10_000
            readTimeout = 60_000
            setRequestProperty("Content-Type", "application/x-protobuf")
            setRequestProperty("User-Agent", DEFAULT_USER_AGENT)
            setRequestProperty("X-Goog-Api-Key", API_KEY)
        }
        return try {
            conn.outputStream.use { it.write(payload) }
            val status = conn.responseCode
            val bytes = (if (status in 200..299) conn.inputStream else conn.errorStream)
                ?.use { it.readBytes() } ?: ByteArray(0)
            if (status !in 200..299)
                throw IOException("HTTP $status: ${bytes.toString(Charsets.UTF_8).take(200)}")
            bytes
        } finally {
            conn.disconnect()
        }
    }

    /* ─────────── Response parser ─────────── */

    private fun extractText(bytes: ByteArray): String {
        val reader = ProtoReader(bytes)
        val allLines = mutableListOf<String>()
        while (reader.hasRemaining()) {
            val tag = reader.readTag() ?: break
            val field = tag ushr 3
            val wire = tag and 0x7
            if (field == 2 && wire == 2) {
                allLines += parseObjectsResponse(reader.readBytes())
            } else {
                reader.skipField(wire)
            }
        }
        return allLines.joinToString("\n").trim()
    }

    private fun parseObjectsResponse(bytes: ByteArray): List<String> {
        val reader = ProtoReader(bytes)
        val lines = mutableListOf<String>()
        while (reader.hasRemaining()) {
            val tag = reader.readTag() ?: break
            val field = tag ushr 3; val wire = tag and 0x7
            if (field == 3 && wire == 2) lines += parseText(reader.readBytes())
            else reader.skipField(wire)
        }
        return lines
    }

    private fun parseText(bytes: ByteArray): List<String> {
        val reader = ProtoReader(bytes)
        val result = mutableListOf<String>()
        while (reader.hasRemaining()) {
            val tag = reader.readTag() ?: break
            val field = tag ushr 3; val wire = tag and 0x7
            if (field == 1 && wire == 2) result += parseTextLayout(reader.readBytes())
            else reader.skipField(wire)
        }
        return result
    }

    private fun parseTextLayout(bytes: ByteArray): List<String> {
        val reader = ProtoReader(bytes)
        val lines = mutableListOf<String>()
        while (reader.hasRemaining()) {
            val tag = reader.readTag() ?: break
            val field = tag ushr 3; val wire = tag and 0x7
            if (field == 1 && wire == 2) lines += parseParagraph(reader.readBytes())
            else reader.skipField(wire)
        }
        return lines
    }

    private fun parseParagraph(bytes: ByteArray): List<String> {
        val reader = ProtoReader(bytes)
        val lines = mutableListOf<String>()
        while (reader.hasRemaining()) {
            val tag = reader.readTag() ?: break
            val field = tag ushr 3; val wire = tag and 0x7
            if (field == 2 && wire == 2) lines += parseLine(reader.readBytes())
            else reader.skipField(wire)
        }
        return lines
    }

    /** A "line" is a sequence of words; each word carries its own trailing separator. */
    private fun parseLine(bytes: ByteArray): String {
        val reader = ProtoReader(bytes)
        val sb = StringBuilder()
        while (reader.hasRemaining()) {
            val tag = reader.readTag() ?: break
            val field = tag ushr 3; val wire = tag and 0x7
            if (field == 1 && wire == 2) {
                sb.append(parseWord(reader.readBytes()))
            } else {
                reader.skipField(wire)
            }
        }
        return sb.toString()
    }

    /** Returns text + separator (e.g. "Hello" + " "). */
    private fun parseWord(bytes: ByteArray): String {
        val reader = ProtoReader(bytes)
        var text = ""
        var separator = ""
        while (reader.hasRemaining()) {
            val tag = reader.readTag() ?: break
            val field = tag ushr 3; val wire = tag and 0x7
            when {
                field == 2 && wire == 2 -> text = reader.readString()
                field == 3 && wire == 2 -> separator = reader.readString()
                else -> reader.skipField(wire)
            }
        }
        return text + separator
    }

    override fun close() {}

    companion object {
        private const val TAG = "Glens"
        private const val LENS_ENDPOINT = "https://lensfrontend-pa.googleapis.com/v1/crupload"
        private const val API_KEY = "AIzaSyDr2UxVnv_U85AbhhY8XSHSIavUW0DC-sY"
        private val DEFAULT_USER_AGENT =
            "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/145.0.0.0 Safari/537.36"
        private const val DEFAULT_CLIENT_LANGUAGE = "ja"
        private const val DEFAULT_CLIENT_REGION = "Asia/Tokyo"
        private const val MAX_IMAGE_DIMENSION = 1500
        private const val PLATFORM_WEB = 3
        private const val SURFACE_CHROMIUM = 4
        private const val AUTO_FILTER = 1
    }
}

/* ────────────────────────────────────────────────
 *  Minimal protobuf reader / writer — no deps
 * ──────────────────────────────────────────────── */

private class ProtoReader(private val bytes: ByteArray) {
    private var pos = 0

    fun hasRemaining() = pos < bytes.size

    fun readTag(): Int? = if (hasRemaining()) readVarint32() else null

    fun readBytes(): ByteArray {
        val len = readVarint32() ?: return ByteArray(0)
        val safeLen = len.coerceAtMost(bytes.size - pos)
        val result = bytes.copyOfRange(pos, pos + safeLen)
        pos += safeLen
        return result
    }

    fun readString(): String = readBytes().toString(Charsets.UTF_8)

    fun skipField(wireType: Int) {
        when (wireType) {
            0 -> readVarint32()
            1 -> { pos += 8; if (pos > bytes.size) pos = bytes.size }
            2 -> { val len = readVarint32() ?: 0; pos += len.coerceAtMost(bytes.size - pos); if (pos > bytes.size) pos = bytes.size }
            5 -> { pos += 4; if (pos > bytes.size) pos = bytes.size }
        }
    }

    private fun readVarint32(): Int? {
        var result = 0; var shift = 0
        while (shift < 32) {
            if (!hasRemaining()) return null
            val b = bytes[pos++].toInt() and 0xFF
            result = result or ((b and 0x7F) shl shift)
            if ((b and 0x80) == 0) return result
            shift += 7
        }
        return result
    }
}

private class ProtoWriter {
    private val out = ByteArrayOutputStream()

    fun writeInt32(fieldNumber: Int, value: Int) {
        writeTag(fieldNumber, 0); writeVarint32(value)
    }

    fun writeUInt64(fieldNumber: Int, value: Long) {
        writeTag(fieldNumber, 0); writeVarint64(value)
    }

    fun writeString(fieldNumber: Int, value: String) {
        writeBytes(fieldNumber, value.toByteArray(Charsets.UTF_8))
    }

    fun writeBytes(fieldNumber: Int, value: ByteArray) {
        writeTag(fieldNumber, 2); writeVarint32(value.size); out.write(value)
    }

    fun writeMessage(fieldNumber: Int, block: (ProtoWriter) -> Unit) {
        val inner = ProtoWriter().also(block).toByteArray()
        writeBytes(fieldNumber, inner)
    }

    fun toByteArray(): ByteArray = out.toByteArray()

    private fun writeTag(field: Int, wire: Int) = writeVarint32((field shl 3) or wire)

    private fun writeVarint32(value: Int) {
        var v = value
        while ((v and 0x7F.inv()) != 0) { out.write((v and 0x7F) or 0x80); v = v ushr 7 }
        out.write(v and 0x7F)
    }

    private fun writeVarint64(value: Long) {
        var v = value
        while ((v and 0x80L.inv()) != 0L) { out.write(((v and 0x7F) or 0x80).toInt()); v = v ushr 7 }
        out.write((v and 0x7F).toInt())
    }
}

