        c.drawRect(rect.right.toFloat(), rect.top.toFloat(), w.toFloat(), rect.bottom.toFloat(), fill)
        c.drawRect(rect, border)
        // четыре прямоугольника-ручки по серединам сторон + уголок справа-снизу
        val hw = dp(44f).toFloat()
        val hh = dp(12f).toFloat()
        val cx = rect.centerX().toFloat(); val cy = rect.centerY().toFloat()
        val tops = arrayOf(
            floatArrayOf(cx, rect.top.toFloat()),
            floatArrayOf(cx, rect.bottom.toFloat())
        )
        for (t in tops) c.drawRoundRect(t[0] - hw / 2, t[1] - hh / 2, t[0] + hw / 2, t[1] + hh / 2, 8f, 8f, handlePaint)
        val sides = arrayOf(
            floatArrayOf(rect.left.toFloat(), cy),
            floatArrayOf(rect.right.toFloat(), cy)
        )
        for (t in sides) c.drawRoundRect(t[0] - hh / 2, t[1] - hw / 2, t[0] + hh / 2, t[1] + hw / 2, 8f, 8f, handlePaint)
        c.drawCircle(rect.right.toFloat(), rect.bottom.toFloat(), dp(16f).toFloat(), handlePaint)
    }

    override fun onTouchEvent(ev: MotionEvent): Boolean {
        val x = ev.x.toInt()
        val y = ev.y.toInt()
        when (ev.actionMasked) {
            MotionEvent.ACTION_DOWN -> {
                lastX = ev.x
                lastY = ev.y
                mode = zoneFor(x, y)
                return true
            }
            MotionEvent.ACTION_MOVE -> {
                val s = screenSize()
                val dx = (ev.x - lastX).toInt()
                val dy = (ev.y - lastY).toInt()
                lastX = ev.x
                lastY = ev.y
                applyDrag(s, dx, dy)
                invalidate()
                return true
            }
            MotionEvent.ACTION_UP, MotionEvent.ACTION_CANCEL -> {
                mode = 0
                return true
            }
        }
        return super.onTouchEvent(ev)
    }

    private fun zoneFor(x: Int, y: Int): Int {
        val nearL = Math.abs(x - rect.left) <= zone
        val nearR = Math.abs(x - rect.right) <= zone
        val nearT = Math.abs(y - rect.top) <= zone
        val nearB = Math.abs(y - rect.bottom) <= zone
        // углы имеют приоритет
        if (nearL && nearT) return 1
        if (nearR && nearT) return 2
        if (nearL && nearB) return 3
        if (nearR && nearB) return 4
        if (nearL) return 5
        if (nearR) return 6
        if (nearT) return 7
        if (nearB) return 8
        return if (rect.contains(x, y)) -6 else 0
    }

    private fun applyDrag(s: Point, dx: Int, dy: Int) {
        val minW = dp(80)
        val minH = dp(80)
        fun clampSides() {
            if (rect.left < 0) rect.left = 0
            if (rect.top < 0) rect.top = 0
            if (rect.right > s.x) rect.right = s.x
            if (rect.bottom > s.y) rect.bottom = s.y
            if (rect.right - rect.left < minW) rect.right = rect.left + minW
            if (rect.bottom - rect.top < minH) rect.bottom = rect.top + minH
        }
        when (mode) {
            -6 -> rect.offset(dx, dy)
            1 -> { rect.left += dx; rect.top += dy }
            2 -> { rect.right += dx; rect.top += dy }
            3 -> { rect.left += dx; rect.bottom += dy }
            4 -> { rect.right += dx; rect.bottom += dy }
            5 -> rect.left += dx
            6 -> rect.right += dx
            7 -> rect.top += dy
            8 -> rect.bottom += dy
        }
        clampSides()
    }
}

