        assertEquals(Engines.LENS, Engines.normalize(""))
        assertEquals(Engines.LENS, Engines.normalize(null))
        assertEquals(Engines.ZEN, Engines.normalize(Engines.ZEN))
    }

    @Test
    fun `title is stable and non empty`() {
