object RuText {
    fun clean(raw: String): String {
        var s = raw
            // код-блоки: убираем маркеры, но сохраняем текст внутри
            .replace("```", " ")
            // приписки LLM («Перевод:», «Here is:»); (?iu) — регистронезависимо
            // с учётом Unicode, иначе «Перевод:» не совпадёт с «перевод».
            .replace(Regex("(?iu)^(here is|extracted|translation|перевод)[:\\s]*"), "")
            .replace('ё', 'е')
            .replace('Ё', 'Е')
        val lines = s.split('\n').map { line ->
            val kept = line.split(Regex("\\s+")).filter { w ->
                if (w.isEmpty()) false
                else {
                    val cyr = w.count { it in '\u0400'..'\u04FF' }
                    val lat = w.count { it in 'A'..'Z' || it in 'a'..'z' }
                    cyr >= lat || w.length <= 2
                }
            }
            kept.joinToString(" ")
        }.filter { it.isNotBlank() }
        return lines.joinToString("\n").replace(Regex("[ \t]+"), " ").trim()
    }

    fun preferRussianPrompt(): Boolean = true
}

