@@ -1,56 +1,56 @@
 plugins {
     id 'com.android.application'
     id 'org.jetbrains.kotlin.android'
 }

 android {
     namespace 'app.yomikaioverlay'
     compileSdk 34

     defaultConfig {
         applicationId 'app.yomikaioverlay'
         minSdk 26
         targetSdk 34
-        versionCode 5
