+        versionCode 6
+        versionName '1.5'
     }

     signingConfigs {
         release {
             storeFile file('../keystore/yomikai-overlay.jks')
             storePassword 'yomikai'
             keyAlias 'overlay'
             keyPassword 'yomikai'
         }
     }

     buildTypes {
         release {
             signingConfig signingConfigs.release
             minifyEnabled false
         }
         debug {
         }
     }

     compileOptions {
         sourceCompatibility JavaVersion.VERSION_17
         targetCompatibility JavaVersion.VERSION_17
     }
     kotlinOptions {
         jvmTarget = '17'
         // LiteRT 2.1.6 собран на более новом Kotlin: метаданные читаем так.
